import{U as e,W as t,nt as n,t as r}from"./chunks/framework.DU75x1fv.js";var i=JSON.parse(`{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}`),a={name:`privacy.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>Last updated: January 25, 2022</p><p>This Privacy Policy describes Our policies and procedures on the collection, use and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You.</p><p>We use Your Personal data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy.</p><h1 id="interpretation-and-definitions" tabindex="-1">Interpretation and Definitions <a class="header-anchor" href="#interpretation-and-definitions" aria-label="Permalink to “Interpretation and Definitions”">​</a></h1><h2 id="interpretation" tabindex="-1">Interpretation <a class="header-anchor" href="#interpretation" aria-label="Permalink to “Interpretation”">​</a></h2><p>The words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural.</p><h2 id="definitions" tabindex="-1">Definitions <a class="header-anchor" href="#definitions" aria-label="Permalink to “Definitions”">​</a></h2><p>For the purposes of this Privacy Policy:</p><ul><li><p><strong>Account</strong> means a unique account created for You to access our Service or parts of our Service.</p></li><li><p><strong>Application</strong> means the software program provided by the Company downloaded by You on any electronic device, named Nekogram</p></li><li><p><strong>Company</strong> (referred to as either &quot;the Company&quot;, &quot;We&quot;, &quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to Nekogram.</p></li><li><p><strong>Country</strong> refers to: Hong Kong SAR China</p></li><li><p><strong>Device</strong> means any device that can access the Service such as a computer, a cellphone or a digital tablet.</p></li><li><p><strong>Personal Data</strong> is any information that relates to an identified or identifiable individual.</p></li><li><p><strong>Service</strong> refers to the Application.</p></li><li><p><strong>Usage Data</strong> refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit).</p></li><li><p><strong>You</strong> means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable.</p></li></ul><h1 id="collecting-and-using-your-personal-data" tabindex="-1">Collecting and Using Your Personal Data <a class="header-anchor" href="#collecting-and-using-your-personal-data" aria-label="Permalink to “Collecting and Using Your Personal Data”">​</a></h1><h2 id="types-of-data-collected" tabindex="-1">Types of Data Collected <a class="header-anchor" href="#types-of-data-collected" aria-label="Permalink to “Types of Data Collected”">​</a></h2><h3 id="personal-data" tabindex="-1">Personal Data <a class="header-anchor" href="#personal-data" aria-label="Permalink to “Personal Data”">​</a></h3><p>While using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. The data is collected soly for the usage of Telegram API, We do not store or use any of this information. Personally identifiable information may include, but is not limited to:</p><ul><li><p>Email address</p></li><li><p>First name and last name</p></li><li><p>Phone number</p></li><li><p>Usage Data</p></li></ul><h3 id="usage-data" tabindex="-1">Usage Data <a class="header-anchor" href="#usage-data" aria-label="Permalink to “Usage Data”">​</a></h3><p>Usage Data is collected automatically when using the Service.</p><p>Usage Data may include information such as Your Device&#39;s Internet Protocol address (e.g. IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers and other diagnostic data.</p><p>When You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.</p><h3 id="information-collected-while-using-the-application" tabindex="-1">Information Collected while Using the Application <a class="header-anchor" href="#information-collected-while-using-the-application" aria-label="Permalink to “Information Collected while Using the Application”">​</a></h3><p>While using Our Application, in order to provide features of Our Application, We may collect, with Your prior permission:</p><ul><li>Information regarding your location</li><li>Information from your Device&#39;s phone book (contacts list)</li><li>Pictures and other information from your Device&#39;s camera and photo library</li></ul><p>We use this information for the usage of Telegram API, We do not store or use any of this information.</p><p>You can enable or disable access to this information at any time, through Your Device settings.</p><h2 id="use-of-your-personal-data" tabindex="-1">Use of Your Personal Data <a class="header-anchor" href="#use-of-your-personal-data" aria-label="Permalink to “Use of Your Personal Data”">​</a></h2><p>The Company may use Personal Data for the following purposes:</p><ul><li><strong>To provide and maintain our Service</strong>, the data is collected soly for the usage of Telegram API, We do not store or use any of this information.</li></ul><h2 id="retention-of-your-personal-data" tabindex="-1">Retention of Your Personal Data <a class="header-anchor" href="#retention-of-your-personal-data" aria-label="Permalink to “Retention of Your Personal Data”">​</a></h2><p>The Company will retain Your Personal Data only for as long as is necessary for the purposes set out in this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply with our legal obligations (for example, if we are required to retain your data to comply with applicable laws), resolve disputes, and enforce our legal agreements and policies.</p><p>The Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer time periods.</p><h2 id="transfer-of-your-personal-data" tabindex="-1">Transfer of Your Personal Data <a class="header-anchor" href="#transfer-of-your-personal-data" aria-label="Permalink to “Transfer of Your Personal Data”">​</a></h2><p>Your information, including Personal Data, is processed at the Company&#39;s operating offices and in any other places where the parties involved in the processing are located. It means that this information may be transferred to — and maintained on — computers located outside of Your state, province, country or other governmental jurisdiction where the data protection laws may differ than those from Your jurisdiction.</p><p>Your consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer.</p><p>The Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place including the security of Your data and other personal information.</p><h2 id="disclosure-of-your-personal-data" tabindex="-1">Disclosure of Your Personal Data <a class="header-anchor" href="#disclosure-of-your-personal-data" aria-label="Permalink to “Disclosure of Your Personal Data”">​</a></h2><h3 id="business-transactions" tabindex="-1">Business Transactions <a class="header-anchor" href="#business-transactions" aria-label="Permalink to “Business Transactions”">​</a></h3><p>If the Company is involved in a merger, acquisition or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy.</p><h3 id="law-enforcement" tabindex="-1">Law enforcement <a class="header-anchor" href="#law-enforcement" aria-label="Permalink to “Law enforcement”">​</a></h3><p>Under certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g. a court or a government agency).</p><h3 id="other-legal-requirements" tabindex="-1">Other legal requirements <a class="header-anchor" href="#other-legal-requirements" aria-label="Permalink to “Other legal requirements”">​</a></h3><p>The Company may disclose Your Personal Data in the good faith belief that such action is necessary to:</p><ul><li>Comply with a legal obligation</li><li>Protect and defend the rights or property of the Company</li><li>Prevent or investigate possible wrongdoing in connection with the Service</li><li>Protect the personal safety of Users of the Service or the public</li><li>Protect against legal liability</li></ul><h2 id="security-of-your-personal-data" tabindex="-1">Security of Your Personal Data <a class="header-anchor" href="#security-of-your-personal-data" aria-label="Permalink to “Security of Your Personal Data”">​</a></h2><p>The security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage is 100% secure. While We strive to use commercially acceptable means to protect Your Personal Data, We cannot guarantee its absolute security.</p><h1 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to “Children&#39;s Privacy”">​</a></h1><p>Our Service does not address anyone under the age of 13. We do not knowingly collect personally identifiable information from anyone under the age of 13. If You are a parent or guardian and You are aware that Your child has provided Us with Personal Data, please contact Us. If We become aware that We have collected Personal Data from anyone under the age of 13 without verification of parental consent, We take steps to remove that information from Our servers.</p><p>If We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent&#39;s consent before We collect and use that information.</p><h1 id="links-to-other-websites" tabindex="-1">Links to Other Websites <a class="header-anchor" href="#links-to-other-websites" aria-label="Permalink to “Links to Other Websites”">​</a></h1><p>Our Service may contain links to other websites that are not operated by Us. If You click on a third party link, You will be directed to that third party&#39;s site. We strongly advise You to review the Privacy Policy of every site You visit.</p><p>We have no control over and assume no responsibility for the content, privacy policies or practices of any third party sites or services.</p><h1 id="changes-to-this-privacy-policy" tabindex="-1">Changes to this Privacy Policy <a class="header-anchor" href="#changes-to-this-privacy-policy" aria-label="Permalink to “Changes to this Privacy Policy”">​</a></h1><p>We may update Our Privacy Policy from time to time. We will notify You of any changes by posting the new Privacy Policy on this page.</p><p>We will let You know via email and/or a prominent notice on Our Service, prior to the change becoming effective and update the &quot;Last updated&quot; date at the top of this Privacy Policy.</p><p>You are advised to review this Privacy Policy periodically for any changes. Changes to this Privacy Policy are effective when they are posted on this page.</p><h1 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to “Contact Us”">​</a></h1><p>If you have any questions about this Privacy Policy, You can contact us:</p><ul><li>By email: <a href="mailto:nekoworkshop@protonmail.com" target="_blank" rel="noreferrer">nekoworkshop@protonmail.com</a></li></ul>`,57)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};